SELECT * FROM (
    SELECT 
      FROM LAW_REVISIONS r
      JOIN TRACKED_LAWS  l ON l.ID = r.TRACKED_LAW_ID


            r.REVIEW_STATUS = #{reviewStatus}


            AND r.TRACKED_LAW_ID = #{trackedLawId}


            AND EXISTS (SELECT 1 FROM DOC_LAW_MAPPINGS m
                         WHERE m.TRACKED_LAW_ID = r.TRACKED_LAW_ID)


     ORDER BY r.DETECTED_AT DESC, r.ID DESC
) WHERE ROWNUM <= #{limit}

